import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { timingSafeEqual } from 'node:crypto';
import { revalidateTag } from 'next/cache';
import { NextResponse, type NextRequest } from 'next/server';

/**
 * Called by the API whenever content is published so visitors see updates immediately.
 * The shared secret is generated by the API in the config volume (mounted read-only here);
 * REVALIDATE_SECRET in the environment overrides it.
 */
function expectedSecret(): string | null {
  if ((process.env.REVALIDATE_SECRET ?? '').length >= 32) return process.env.REVALIDATE_SECRET!;
  try {
    return JSON.parse(readFileSync(join(process.env.CONFIG_DIR ?? '/app/config', 'secrets.json'), 'utf8')).revalidate ?? null;
  } catch {
    return null;
  }
}

export async function POST(req: NextRequest) {
  const expected = expectedSecret();
  const given = req.headers.get('x-revalidate-secret') ?? '';
  const ok = !!expected && given.length === expected.length && timingSafeEqual(Buffer.from(given), Buffer.from(expected));
  if (!ok) return NextResponse.json({ ok: false }, { status: 401 });
  revalidateTag('cms');
  return NextResponse.json({ ok: true, revalidated: Date.now() });
}
